    ).map(::parse)

    data class B(val en: String, val vi: String)
    data class Case(val issue: B, val reason: B, val action: B)
    data class Topic(val id: String, val en: String, val vi: String,
        val context: List<B>, val idiom: B, val cases: List<Case>)
    private fun parse(raw: String): Topic {
        val lines = raw.trimIndent().trim().lines().map { it.split('|') }
        require(lines.size == 10)
        val title = lines[0]
        fun b(parts: List<String>, offset: Int = 0) = B(parts[offset], parts[offset + 1])
        return Topic(title[0], title[1], title[2], lines.slice(1..3).map { b(it) }, b(lines[4]),
            lines.drop(5).map { require(it.size == 6); Case(b(it), b(it, 2), b(it, 4)) })
    }
}
